class Solution:
    def countReplacements(self, ranks: List[int]) -> int:
        best, ans = ranks[0], 0
        for x in ranks[1:]:
            if x < best:
                ans += 1
                best = x
        return ans

c.cpp:
class Solution {
public:
    int countReplacements(vector<int>& ranks) {
        int best = ranks[0], ans = 0;
        for (size_t i = 1; i < ranks.size(); i++) {
            if (ranks[i] < best) { ans++; best = ranks[i]; }
        }
        return ans;
    }
};

